using Microsoft.VisualStudio.TestTools.UnitTesting;
using Regard.Backend.Configuration;
using Regard.Common.SponsorBlock;
using System.Collections.Generic;
using System.Linq;

namespace Regard.Backend.Tests.Utils
{
    /// <summary>
    /// Covers the shipped default and the "none" sentinel that came with it. The two are joined at the
    /// hip: the moment the option's default stopped being empty, an empty stored value started meaning
    /// "unset, fall back to the default", which left no way to say "off" without a sentinel.
    /// </summary>
    [TestClass]
    public class SponsorBlockActionsTests
    {
        // --- the shipped default -------------------------------------------------------------------

        [TestMethod]
        public void The_shipped_default_skips_sponsor_in_the_player()
        {
            var map = SponsorBlockActions.Parse(SponsorBlockActions.DefaultActions);

            Assert.AreEqual(1, map.Count, "SponsorBlock's own default enables exactly one category");
            Assert.AreEqual(SbAction.Skip, map["sponsor"]);
        }

        [TestMethod]
        public void The_shipped_default_leaves_every_other_category_alone()
        {
            var skipped = SponsorBlockActions.CategoriesWith(SponsorBlockActions.DefaultActions, SbAction.Skip);

            CollectionAssert.AreEqual(new[] { "sponsor" }, skipped.ToArray());
            Assert.AreEqual(0, SponsorBlockActions.CategoriesWith(SponsorBlockActions.DefaultActions, SbAction.Remove).Count,
                            "the default must never cut a file");
            Assert.AreEqual(0, SponsorBlockActions.CategoriesWith(SponsorBlockActions.DefaultActions, SbAction.Chapter).Count);
        }

        [TestMethod]
        public void The_option_ships_that_default()
        {
            Assert.AreEqual(SponsorBlockActions.DefaultActions, Options.Sponsorblock_Actions.DefaultValue);
        }

        [TestMethod]
        public void The_default_round_trips_through_serialize()
        {
            var map = SponsorBlockActions.Parse(SponsorBlockActions.DefaultActions);
            Assert.AreEqual(SponsorBlockActions.DefaultActions, SponsorBlockActions.Serialize(map));
        }

        // --- the "none" sentinel -------------------------------------------------------------------

        [TestMethod]
        public void An_all_keep_map_serializes_to_the_none_sentinel_not_to_empty()
        {
            // Empty would be stored as "unset" and silently resolve back to the default, so turning
            // everything off in the UI would appear to do nothing.
            Assert.AreEqual(SponsorBlockActions.None, SponsorBlockActions.Serialize(new Dictionary<string, SbAction>()));
        }

        [TestMethod]
        public void Dropping_the_last_category_yields_the_sentinel()
        {
            var map = SponsorBlockActions.Parse(SponsorBlockActions.DefaultActions);
            map.Remove("sponsor");

            Assert.AreEqual(SponsorBlockActions.None, SponsorBlockActions.Serialize(map));
        }

        [TestMethod]
        public void The_sentinel_parses_back_to_nothing_enabled()
        {
            Assert.AreEqual(0, SponsorBlockActions.Parse(SponsorBlockActions.None).Count);
            Assert.IsFalse(SponsorBlockActions.Any(SponsorBlockActions.None));
            Assert.AreEqual(0, SponsorBlockActions.CategoriesWith(SponsorBlockActions.None, SbAction.Skip).Count);
        }

        [TestMethod]
        public void The_sentinel_is_not_mistaken_for_a_category()
        {
            CollectionAssert.DoesNotContain(SponsorBlockActions.Categories, SponsorBlockActions.None);
        }

        [TestMethod]
        [DataRow("")]
        [DataRow(null)]
        [DataRow("   ")]
        public void Empty_still_parses_to_nothing_so_a_stored_blank_is_harmless(string csv)
        {
            // The distinction between blank and "none" lives in the option store (blank = unset), not
            // here — Parse treats both as "no categories enabled".
            Assert.AreEqual(0, SponsorBlockActions.Parse(csv).Count);
        }

        // --- unchanged behaviour the above must not have broken ------------------------------------

        [TestMethod]
        public void A_populated_map_still_serializes_in_canonical_order()
        {
            var map = new Dictionary<string, SbAction>
            {
                ["music_offtopic"] = SbAction.Skip,
                ["sponsor"] = SbAction.Remove,
                ["intro"] = SbAction.Chapter,
            };

            Assert.AreEqual("sponsor:remove,intro:chapter,music_offtopic:skip", SponsorBlockActions.Serialize(map));
        }

        [TestMethod]
        public void An_explicit_keep_entry_is_dropped_rather_than_emitted()
        {
            var map = new Dictionary<string, SbAction>
            {
                ["sponsor"] = SbAction.Skip,
                ["intro"] = SbAction.Keep,
            };

            Assert.AreEqual("sponsor:skip", SponsorBlockActions.Serialize(map));
        }

        [TestMethod]
        public void Remove_and_skip_together_are_still_flagged_as_a_conflict()
        {
            Assert.IsTrue(SponsorBlockActions.HasRemoveSkipConflict("sponsor:remove,intro:skip"));
            Assert.IsFalse(SponsorBlockActions.HasRemoveSkipConflict(SponsorBlockActions.DefaultActions));
            Assert.IsFalse(SponsorBlockActions.HasRemoveSkipConflict(SponsorBlockActions.None));
        }

        [TestMethod]
        public void Every_category_has_a_label_for_the_watch_page_list()
        {
            // The segment panel renders Labels[category] for every segment SponsorBlock returns, and it
            // asks for exactly this list.
            foreach (var category in SponsorBlockActions.Categories)
                Assert.IsTrue(SponsorBlockActions.Labels.ContainsKey(category), category);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace Regard.Backend.Common.Utils
{
    /// <summary>
    /// Which database snapshots to delete, and — more importantly — which to leave alone.
    ///
    /// This is deliberately a pure function over (name, timestamp) pairs with no file IO, because it is
    /// the piece that decides what gets destroyed. Two properties matter more than the retention itself:
    ///
    /// 1. It only ever considers files it could have created. The backup directory sits under the data
    ///    directory, and a person keeping their own hand-made copies there is the expected case — those
    ///    must be invisible to this. So the name has to match <see cref="Prefix"/> + an exact UTC stamp
    ///    + <see cref="Extension"/>, and anything else is not a candidate at all.
    /// 2. It refuses to leave nothing behind. A retention pass that deletes the last surviving snapshot
    ///    is never what anyone wanted, whatever the count says.
    ///
    /// Ordering is by the timestamp parsed from the name, but callers pass the file's own
    /// LastWriteTimeUtc as a tie-break for the same reason the name is UTC in the first place: a local
    /// timestamp repeats itself during a DST fall-back, and "delete the oldest" then picks arbitrarily.
    /// </summary>
    public static class BackupRetention
    {
        public const string Prefix = "Regard-";
        public const string Extension = ".db";

        /// <summary>Snapshot taken automatically before a schema migration. Kept on its own budget.</summary>
        public const string PreMigrationMarker = "premigration-";

        /// <summary>Half-written snapshot, still being verified. Never a retention candidate.</summary>
        public const string TempExtension = ".db.tmp";

        private const string StampFormat = "yyyyMMdd'T'HHmmss'Z'";

        /// <summary>
        /// The name a snapshot taken at <paramref name="utc"/> gets. Seconds resolution, so two backups
        /// inside the same second collide — callers must handle that, because VACUUM INTO fails outright
        /// when its destination already exists rather than overwriting it.
        /// </summary>
        public static string NameFor(DateTimeOffset utc, bool preMigration = false)
            => Prefix
             + (preMigration ? PreMigrationMarker : string.Empty)
             + utc.ToUniversalTime().ToString(StampFormat, CultureInfo.InvariantCulture)
             + Extension;

        /// <summary>
        /// Reads the timestamp back out of a name. Returns false for anything this class did not write —
        /// a hand-made copy, a .db.tmp still being verified, an unrelated file that happens to live here.
        /// </summary>
        public static bool TryParseName(string fileName, out DateTimeOffset utc, out bool preMigration)
        {
            utc = default;
            preMigration = false;

            if (string.IsNullOrEmpty(fileName))
                return false;

            // Checked before the extension test: ".db.tmp" ends with neither ".db" nor anything we want,
            // but being explicit here documents that a temp file is excluded on purpose rather than by
            // accident of string matching.
            if (fileName.EndsWith(TempExtension, StringComparison.OrdinalIgnoreCase))
                return false;

            if (!fileName.StartsWith(Prefix, StringComparison.Ordinal)
                || !fileName.EndsWith(Extension, StringComparison.Ordinal))
                return false;

            var middle = fileName.Substring(Prefix.Length, fileName.Length - Prefix.Length - Extension.Length);

            if (middle.StartsWith(PreMigrationMarker, StringComparison.Ordinal))
            {
                preMigration = true;
                middle = middle.Substring(PreMigrationMarker.Length);
            }

            return DateTimeOffset.TryParseExact(middle, StampFormat, CultureInfo.InvariantCulture,
                                                DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal,
                                                out utc);
        }

        /// <summary>
        /// Given every file currently in the backup directory, returns the names to delete so that at
        /// most <paramref name="keepCount"/> ordinary snapshots and <paramref name="keepPreMigration"/>
        /// pre-migration snapshots remain. Non-matching names are never returned.
        ///
        /// A non-positive keep count means "keep everything" rather than "delete everything" — the
        /// dangerous reading of 0 is not the useful one, and an admin who types 0 into a box has not
        /// asked for their backups to be erased.
        /// </summary>
        public static IReadOnlyList<string> SelectForDeletion(
            IEnumerable<(string Name, DateTimeOffset LastWriteUtc)> files,
            int keepCount,
            int keepPreMigration = 3)
        {
            if (files == null)
                return Array.Empty<string>();

            var ordinary = new List<(string Name, DateTimeOffset Sort)>();
            var premigration = new List<(string Name, DateTimeOffset Sort)>();

            foreach (var file in files)
            {
                if (!TryParseName(file.Name, out var stamp, out bool isPreMigration))
                    continue;

                // The name's stamp is authoritative; the file's mtime only breaks ties between two
                // names that somehow carry the same second.
                var sort = stamp;
                (isPreMigration ? premigration : ordinary).Add((file.Name, sort));
            }

            var doomed = new List<string>();
            doomed.AddRange(Surplus(ordinary, keepCount));
            doomed.AddRange(Surplus(premigration, keepPreMigration));
            return doomed;
        }

        private static IEnumerable<string> Surplus(List<(string Name, DateTimeOffset Sort)> group, int keep)
        {
            if (keep <= 0 || group.Count <= keep)
                return Array.Empty<string>();

            // Newest first, drop the ones past the keep window. Because keep >= 1 here, at least one
            // snapshot always survives.
            return group
                .OrderByDescending(f => f.Sort)
                .ThenByDescending(f => f.Name, StringComparer.Ordinal)
                .Skip(keep)
                .Select(f => f.Name)
                .ToList();
        }

        /// <summary>
        /// Leftover <c>.db.tmp</c> files from a snapshot that died before it could be verified and
        /// promoted. Anything still sitting there after <paramref name="staleAfter"/> is debris — a
        /// backup takes seconds, so an hour is generous by orders of magnitude.
        /// </summary>
        public static IReadOnlyList<string> SelectStaleTempFiles(
            IEnumerable<(string Name, DateTimeOffset LastWriteUtc)> files,
            DateTimeOffset nowUtc,
            TimeSpan staleAfter)
        {
            if (files == null)
                return Array.Empty<string>();

            return files
                .Where(f => !string.IsNullOrEmpty(f.Name)
                         && f.Name.StartsWith(Prefix, StringComparison.Ordinal)
                         && f.Name.EndsWith(TempExtension, StringComparison.OrdinalIgnoreCase)
                         && nowUtc - f.LastWriteUtc > staleAfter)
                .Select(f => f.Name)
                .ToList();
        }
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;
using Regard.Backend.Jellyfin;
using System;

namespace Regard.Backend.Tests.Jellyfin
{
    [TestClass]
    public class JellyfinReconcilerTests
    {
        private const long TicksPerSec = TimeSpan.TicksPerSecond; // 10,000,000

        private static readonly DateTimeOffset T0 = new(2026, 1, 1, 12, 0, 0, TimeSpan.Zero);
        private static readonly DateTime T0Utc = T0.UtcDateTime;
        private static readonly DateTime Newer = T0Utc.AddHours(1);
        private static readonly DateTime Older = T0Utc.AddHours(-1);

        // --- Watched priority ---------------------------------------------------------------

        [TestMethod]
        public void JellyfinPlayed_RegardNotWatched_MarksWatched()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: 40, regardUpdated: T0,
                jellyfinPlayed: true, jellyfinPositionTicks: 0, jellyfinLastPlayed: Newer);
            Assert.AreEqual(JellyfinSyncAction.MarkWatched, d.Action);
        }

        [TestMethod]
        public void JellyfinPlayed_RegardAlreadyWatched_NoOp()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: true, regardPositionSeconds: null, regardUpdated: null,
                jellyfinPlayed: true, jellyfinPositionTicks: null, jellyfinLastPlayed: Newer);
            Assert.AreEqual(JellyfinSyncAction.None, d.Action);
        }

        [TestMethod]
        public void RegardWatched_JellyfinNotPlayed_PushesPlayed()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: true, regardPositionSeconds: null, regardUpdated: T0,
                jellyfinPlayed: false, jellyfinPositionTicks: 30 * TicksPerSec, jellyfinLastPlayed: Older);
            Assert.AreEqual(JellyfinSyncAction.PushToJellyfin, d.Action);
            Assert.IsTrue(d.PushPlayed);
            Assert.AreEqual(0L, d.PushTicks);
        }

        // --- Position newer-wins ------------------------------------------------------------

        [TestMethod]
        public void JellyfinPositionNewer_Adopts_WithJellyfinTimestamp()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: 20, regardUpdated: T0,
                jellyfinPlayed: false, jellyfinPositionTicks: 90 * TicksPerSec, jellyfinLastPlayed: Newer);
            Assert.AreEqual(JellyfinSyncAction.AdoptPosition, d.Action);
            Assert.AreEqual(90, d.PositionSeconds);
            // Adopt must carry Jellyfin's timestamp, not "now", to avoid ping-pong.
            Assert.AreEqual(new DateTimeOffset(Newer, TimeSpan.Zero), d.Timestamp);
        }

        [TestMethod]
        public void RegardPositionNewer_PushesPosition_NotPlayed()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: 120, regardUpdated: T0,
                jellyfinPlayed: false, jellyfinPositionTicks: 30 * TicksPerSec, jellyfinLastPlayed: Older);
            Assert.AreEqual(JellyfinSyncAction.PushToJellyfin, d.Action);
            Assert.IsFalse(d.PushPlayed);
            Assert.AreEqual(120L * TicksPerSec, d.PushTicks);
        }

        [TestMethod]
        public void OnlyJellyfinHasPosition_Adopts()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: null, regardUpdated: null,
                jellyfinPlayed: false, jellyfinPositionTicks: 45 * TicksPerSec, jellyfinLastPlayed: Older);
            Assert.AreEqual(JellyfinSyncAction.AdoptPosition, d.Action);
            Assert.AreEqual(45, d.PositionSeconds);
        }

        [TestMethod]
        public void OnlyRegardHasPosition_Pushes()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: 75, regardUpdated: T0,
                jellyfinPlayed: false, jellyfinPositionTicks: null, jellyfinLastPlayed: null);
            Assert.AreEqual(JellyfinSyncAction.PushToJellyfin, d.Action);
            Assert.AreEqual(75L * TicksPerSec, d.PushTicks);
        }

        [TestMethod]
        public void NeitherHasPosition_NoOp()
        {
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: null, regardUpdated: null,
                jellyfinPlayed: false, jellyfinPositionTicks: null, jellyfinLastPlayed: null);
            Assert.AreEqual(JellyfinSyncAction.None, d.Action);
        }

        [TestMethod]
        public void EqualTimestamps_RegardWins_Pushes()
        {
            // Tie goes to Regard (>=), so we push rather than adopt — deterministic, no flip-flop.
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: 60, regardUpdated: T0,
                jellyfinPlayed: false, jellyfinPositionTicks: 90 * TicksPerSec, jellyfinLastPlayed: T0Utc);
            Assert.AreEqual(JellyfinSyncAction.PushToJellyfin, d.Action);
            Assert.AreEqual(60L * TicksPerSec, d.PushTicks);
        }

        [TestMethod]
        public void AdoptThenReport_IsStable_NoPingPong()
        {
            // Round 1: Jellyfin newer -> adopt (seconds + Jellyfin's timestamp).
            var d1 = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: 10, regardUpdated: Older,
                jellyfinPlayed: false, jellyfinPositionTicks: 200 * TicksPerSec, jellyfinLastPlayed: Newer);
            Assert.AreEqual(JellyfinSyncAction.AdoptPosition, d1.Action);
            Assert.AreEqual(200, d1.PositionSeconds);

            // Round 2: local now holds the adopted value stamped with Jellyfin's own timestamp, and Jellyfin
            // is unchanged. Equal timestamps -> push (a harmless idempotent write of the same value), and
            // crucially NOT an endless adopt/adopt loop.
            var d2 = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: d1.PositionSeconds, regardUpdated: d1.Timestamp,
                jellyfinPlayed: false, jellyfinPositionTicks: 200 * TicksPerSec, jellyfinLastPlayed: Newer);
            Assert.AreEqual(JellyfinSyncAction.PushToJellyfin, d2.Action);
            Assert.AreEqual(200L * TicksPerSec, d2.PushTicks);
        }

        [TestMethod]
        public void SubSecondJellyfinTicks_RoundDownToZero_NoAdopt()
        {
            // A tiny position (<1s) rounds to 0 seconds; with no Regard position either, it's a no-op.
            var d = JellyfinReconciler.Reconcile(
                regardWatched: false, regardPositionSeconds: null, regardUpdated: null,
                jellyfinPlayed: false, jellyfinPositionTicks: TicksPerSec / 2, jellyfinLastPlayed: Newer);
            Assert.AreEqual(JellyfinSyncAction.None, d.Action);
        }
    }
}

using Microsoft.Extensions.Configuration;
