namespace Regard.Backend.Tests
{
    /// <summary>
    /// Guards which files a video "owns". This decides what "Download again" and "Delete downloaded
    /// files" destroy, so a matching bug here costs the user data that isn't recoverable from the app.
    /// </summary>
    [TestClass]
    public class VideoStorageFileMatchingTests
    {
        private string root;
        private VideoStorageService storage;

        [TestInitialize]
        public void Setup()
        {
            root = Path.Combine(Path.GetTempPath(), "regard-storage-tests", Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(root);
            storage = new VideoStorageService(NullLogger<VideoStorageService>.Instance, StorageManagerFor(root));
        }

        [TestCleanup]
        public void Cleanup()
        {
            try { Directory.Delete(root, recursive: true); } catch { /* best effort */ }
        }

        private void Touch(params string[] relativePaths)
        {
            foreach (var rel in relativePaths)
            {
                var full = Path.Combine(root, rel);
                Directory.CreateDirectory(Path.GetDirectoryName(full));
                File.WriteAllText(full, "x");
            }
        }

        private async Task<List<string>> FilesAt(string prefix)
        {
            var found = new List<string>();
            await foreach (var f in storage.GetFilesAt(prefix))
                found.Add(Path.GetFileName(f));
            found.Sort(StringComparer.Ordinal);
            return found;
        }

        [TestMethod]
        public async Task CollectsEveryOutputOfOneVideo()
        {
            Touch(
                "CGP Grey/S2025E1 - Foo.mp4",
                "CGP Grey/S2025E1 - Foo.en.vtt",
                "CGP Grey/S2025E1 - Foo.ro.vtt",
                "CGP Grey/S2025E1 - Foo.info.json",
                "CGP Grey/S2025E1 - Foo.f315.webm.part");

            var found = await FilesAt("CGP Grey/S2025E1 - Foo");

            Assert.AreEqual(5, found.Count, string.Join(", ", found));
            CollectionAssert.Contains(found, "S2025E1 - Foo.f315.webm.part", "a stale .part must be swept");
            CollectionAssert.Contains(found, "S2025E1 - Foo.info.json");
        }

        [TestMethod]
        public async Task DoesNotClaimASiblingWithALongerName()
        {
            // The reason a bare StartsWith is unsafe: forcing a re-download of "Foo" would otherwise
            // delete "Foo (Part 2)"'s media and subtitles, with nothing to restore them from.
            Touch(
                "Sub/S1E1 - Foo.mp4",
                "Sub/S1E1 - Foo.en.vtt",
                "Sub/S1E1 - Foo (Part 2).mp4",
                "Sub/S1E1 - Foo (Part 2).en.vtt",
                "Sub/S1E1 - Foobar.mp4");

            var found = await FilesAt("Sub/S1E1 - Foo");

            CollectionAssert.AreEquivalent(
                new[] { "S1E1 - Foo.mp4", "S1E1 - Foo.en.vtt" }, found,
                "only the exact video's own outputs: " + string.Join(", ", found));
        }

        [TestMethod]
        public async Task ClaimsTheDashSuffixedJellyfinThumbnail()
        {
            // WriteEpisodeMetadata renames artwork to "<name>-thumb.jpg" with a DASH, not a dot — the one
            // output that doesn't follow the dot convention. Missing it orphans a thumbnail per
            // re-download.
            Touch(
                "Sub/S1E1 - Foo.mp4",
                "Sub/S1E1 - Foo.nfo",
                "Sub/S1E1 - Foo-thumb.jpg");

            var found = await FilesAt("Sub/S1E1 - Foo");

            Assert.AreEqual(3, found.Count, string.Join(", ", found));
            CollectionAssert.Contains(found, "S1E1 - Foo-thumb.jpg");
        }

        [TestMethod]
        public async Task DoesNotClaimASiblingStartingWithDashThumb()
        {
            // The trailing dot in "-thumb." is what keeps this precise.
            Touch(
                "Sub/S1E1 - Foo.mp4",
                "Sub/S1E1 - Foo-thumbnail deep dive.mp4");

            var found = await FilesAt("Sub/S1E1 - Foo");

            CollectionAssert.AreEquivalent(new[] { "S1E1 - Foo.mp4" }, found, string.Join(", ", found));
        }

        [TestMethod]
        public async Task HandlesATitleThatEndsWithADot()
        {
            // Real case from the dev library: "You Need To Quit Weed." — the prefix carries the dot, so
            // its outputs have two.
            Touch(
                "Sub/S1E1 - Quit Weed..mp4",
                "Sub/S1E1 - Quit Weed..en.vtt");

            var found = await FilesAt("Sub/S1E1 - Quit Weed.");

            Assert.AreEqual(2, found.Count, string.Join(", ", found));
        }

        [TestMethod]
        public async Task MatchesAnExtensionlessFileExactly()
        {
            Touch("Sub/S1E1 - Bare");

            var found = await FilesAt("Sub/S1E1 - Bare");

            CollectionAssert.AreEquivalent(new[] { "S1E1 - Bare" }, found);
        }

        [TestMethod]
        public async Task EmptyOrMissingInputsYieldNothing()
        {
            Assert.AreEqual(0, (await FilesAt(null)).Count);
            Assert.AreEqual(0, (await FilesAt("")).Count);
            Assert.AreEqual(0, (await FilesAt("No Such Dir/Nope")).Count);
        }

        [TestMethod]
        public async Task DeleteAtRemovesOnlyTheVideosOwnFiles()
        {
            Touch(
                "Sub/S1E1 - Foo.mp4",
                "Sub/S1E1 - Foo.en.vtt",
                "Sub/S1E1 - Foo.f315.webm.part",
                "Sub/S1E1 - Foo (Part 2).mp4");

            int deleted = await storage.DeleteAt("Sub/S1E1 - Foo");

            Assert.AreEqual(3, deleted);
            Assert.IsTrue(File.Exists(Path.Combine(root, "Sub/S1E1 - Foo (Part 2).mp4")),
                          "a sibling video must survive");
            Assert.IsFalse(File.Exists(Path.Combine(root, "Sub/S1E1 - Foo.mp4")));
            Assert.IsFalse(File.Exists(Path.Combine(root, "Sub/S1E1 - Foo.f315.webm.part")));
        }

        [TestMethod]
        public async Task GetFilesReturnsNothingForAVideoThatNeverFinished()
        {
            // DownloadedPath is written only on success, so a half-finished download is invisible to
            // GetFiles. This is why the forced re-download also sweeps the resolved output path.
            Touch("Sub/S1E1 - Half.f315.webm.part");

            var viaVideo = new List<string>();
            await foreach (var f in storage.GetFiles(new Video { DownloadedPath = null }))
                viaVideo.Add(f);

            Assert.AreEqual(0, viaVideo.Count, "nothing findable through the Video");
            Assert.AreEqual(1, (await FilesAt("Sub/S1E1 - Half")).Count, "but findable by path");
        }

        private static StorageManager StorageManagerFor(string downloadRoot)
        {
            var config = new ConfigurationBuilder()
                .AddInMemoryCollection(new Dictionary<string, string>
                {
                    ["DownloadDirectory"] = downloadRoot,
                    ["DataDirectory"] = downloadRoot,
                })
                .Build();
            return new StorageManager(NullLogger<VideoStorageService>.Instance, config);
        }
    }
}

using Microsoft.VisualStudio.TestTools.UnitTesting;
using Regard.Backend.Common.Utils;
using System;
using System.Collections.Generic;
using System.Linq;

namespace Regard.Backend.Tests.Utils
{
    /// <summary>
    /// Retention decides what gets deleted, so these tests are weighted towards what must NOT happen
    /// rather than towards the happy path. The backup directory lives under the data directory, where
    /// hand-made copies are the expected case, and this code runs unattended at 3am.
    /// </summary>
    [TestClass]
    public class BackupRetentionTests
    {
        private static readonly DateTimeOffset Now =
            new DateTimeOffset(2026, 9, 3, 12, 0, 0, TimeSpan.Zero);

        private static (string, DateTimeOffset) At(int daysAgo, bool preMigration = false)
        {
            var stamp = Now.AddDays(-daysAgo);
            return (BackupRetention.NameFor(stamp, preMigration), stamp);
        }

        private static List<(string, DateTimeOffset)> Series(int count, bool preMigration = false)
            => Enumerable.Range(1, count).Select(d => At(d, preMigration)).ToList();

        // ---------------------------------------------------------------- naming round-trip

        [TestMethod]
        public void NameFor_round_trips_through_TryParseName()
        {
            var name = BackupRetention.NameFor(Now);

            Assert.IsTrue(BackupRetention.TryParseName(name, out var parsed, out bool pre));
            Assert.AreEqual(Now.ToUnixTimeSeconds(), parsed.ToUnixTimeSeconds());
            Assert.IsFalse(pre);
        }

        [TestMethod]
        public void NameFor_uses_UTC_so_a_DST_fallback_cannot_produce_two_identical_names()
        {
            // 2026-10-25 01:30 UTC is 03:30 and then again 02:30 in a CET/CEST fall-back. Two distinct
            // instants an hour apart must not collapse to the same file name, because retention orders
            // by that name and "delete the oldest" would otherwise pick arbitrarily.
            var first = new DateTimeOffset(2026, 10, 25, 2, 30, 0, TimeSpan.FromHours(2));
            var second = new DateTimeOffset(2026, 10, 25, 2, 30, 0, TimeSpan.FromHours(1));

            Assert.AreNotEqual(BackupRetention.NameFor(first), BackupRetention.NameFor(second));
        }

        [TestMethod]
        public void PreMigration_names_round_trip_and_are_flagged()
        {
            var name = BackupRetention.NameFor(Now, preMigration: true);

            StringAssert.Contains(name, "premigration");
            Assert.IsTrue(BackupRetention.TryParseName(name, out _, out bool pre));
            Assert.IsTrue(pre);
        }

        // ---------------------------------------------------------------- what is NOT a candidate

        [TestMethod]
        [DataRow("Regard.db")]                                  // the live database itself
        [DataRow("Regard.db-wal")]
        [DataRow("Regard.db-shm")]
        [DataRow("Regard.db.20260830-220853-pre-batch5a.bak")]  // a real hand-made copy from this repo
        [DataRow("Regard-20260903T120000Z.db.tmp")]             // half-written, still being verified
        [DataRow("Regard-notatimestamp.db")]
        [DataRow("Regard-20260903T120000Z.sqlite")]             // right stamp, wrong extension
        [DataRow("regard-20260903T120000Z.db")]                 // wrong case on the prefix
        [DataRow("jwt-secret")]
        [DataRow("")]
        public void TryParseName_rejects_anything_this_class_did_not_write(string name)
        {
            Assert.IsFalse(BackupRetention.TryParseName(name, out _, out _),
                $"'{name}' must not be treated as a backup");
        }

        [TestMethod]
        public void SelectForDeletion_never_returns_a_file_it_does_not_recognise()
        {
            var files = Series(20);
            files.Add(("Regard.db", Now));
            files.Add(("jwt-secret", Now));
            files.Add(("Regard.db.20260830-220853-pre-batch5a.bak", Now.AddDays(-30)));
            files.Add(("Regard-20260101T000000Z.db.tmp", Now.AddDays(-200)));

            var doomed = BackupRetention.SelectForDeletion(files, keepCount: 7);

            foreach (var stranger in new[] { "Regard.db", "jwt-secret",
                                             "Regard.db.20260830-220853-pre-batch5a.bak",
                                             "Regard-20260101T000000Z.db.tmp" })
                CollectionAssert.DoesNotContain(doomed.ToList(), stranger);
        }

        // ---------------------------------------------------------------- the retention itself

        [TestMethod]
        public void SelectForDeletion_keeps_the_newest_N()
        {
            var files = Series(20);   // 1..20 days ago

            var doomed = BackupRetention.SelectForDeletion(files, keepCount: 7).ToHashSet();
            var survivors = files.Select(f => f.Item1).Where(n => !doomed.Contains(n)).ToList();

            Assert.AreEqual(7, survivors.Count);
            // the survivors are exactly days 1..7 ago
            foreach (var day in Enumerable.Range(1, 7))
                CollectionAssert.Contains(survivors, At(day).Item1);
        }

        [TestMethod]
        public void SelectForDeletion_does_nothing_when_under_the_limit()
        {
            Assert.AreEqual(0, BackupRetention.SelectForDeletion(Series(3), keepCount: 7).Count);
        }

        [TestMethod]
        public void SelectForDeletion_treats_a_non_positive_keep_count_as_keep_everything()
        {
            // The dangerous reading of 0 is not the useful one. An admin typing 0 into a box has not
            // asked to have every snapshot erased.
            Assert.AreEqual(0, BackupRetention.SelectForDeletion(Series(20), keepCount: 0).Count);
            Assert.AreEqual(0, BackupRetention.SelectForDeletion(Series(20), keepCount: -5).Count);
        }

        [TestMethod]
        public void SelectForDeletion_always_leaves_at_least_one_survivor()
        {
            for (int total = 1; total <= 12; total++)
            {
                var files = Series(total);
                var doomed = BackupRetention.SelectForDeletion(files, keepCount: 1);
                Assert.IsTrue(files.Count - doomed.Count >= 1,
                    $"with {total} files and keepCount 1, nothing survived");
            }
        }

        [TestMethod]
        public void PreMigration_snapshots_are_on_their_own_budget()
        {
            // 10 ordinary + 5 pre-migration. Keeping 7 ordinary must not consume the pre-migration
            // allowance, and vice versa — the whole point of the pre-migration snapshot is that it
            // survives the routine churn that follows an upgrade.
            var files = Series(10).Concat(Series(5, preMigration: true)).ToList();

            var doomed = BackupRetention.SelectForDeletion(files, keepCount: 7, keepPreMigration: 3).ToHashSet();
            var survivors = files.Select(f => f.Item1).Where(n => !doomed.Contains(n)).ToList();

            Assert.AreEqual(7, survivors.Count(n => !n.Contains("premigration")));
            Assert.AreEqual(3, survivors.Count(n => n.Contains("premigration")));
        }

        [TestMethod]
        public void A_flood_of_ordinary_backups_cannot_evict_a_premigration_snapshot()
        {
            var files = Series(200).Concat(Series(1, preMigration: true)).ToList();

            var doomed = BackupRetention.SelectForDeletion(files, keepCount: 7).ToHashSet();

            Assert.IsFalse(doomed.Contains(At(1, preMigration: true).Item1));
        }

        [TestMethod]
        public void SelectForDeletion_tolerates_null_and_empty_input()
        {
            Assert.AreEqual(0, BackupRetention.SelectForDeletion(null, 7).Count);
            Assert.AreEqual(0, BackupRetention.SelectForDeletion(
                Array.Empty<(string, DateTimeOffset)>(), 7).Count);
        }

        // ---------------------------------------------------------------- temp-file debris

        [TestMethod]
        public void Stale_temp_files_are_swept_but_fresh_ones_are_left_alone()
        {
            var files = new[]
            {
                ("Regard-20260903T110000Z.db.tmp", Now.AddMinutes(-2)),    // a backup in flight
                ("Regard-20260902T110000Z.db.tmp", Now.AddHours(-5)),      // debris
                ("Regard-20260901T110000Z.db",     Now.AddDays(-2)),       // a real backup
                ("Regard.db",                      Now),
            };

            var stale = BackupRetention.SelectStaleTempFiles(files, Now, TimeSpan.FromHours(1));

            CollectionAssert.AreEquivalent(new[] { "Regard-20260902T110000Z.db.tmp" }, stale.ToList());
        }

        [TestMethod]
        public void The_temp_sweep_never_touches_a_real_backup_or_the_live_database()
        {
            var files = Series(5).Select(f => (f.Item1, Now.AddDays(-99))).ToList();
            files.Add(("Regard.db", Now.AddDays(-99)));

            Assert.AreEqual(0, BackupRetention.SelectStaleTempFiles(files, Now, TimeSpan.FromHours(1)).Count);
        }
    }
}

using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Regard.Backend.Model;
using Regard.Backend.Services;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

namespace Regard.Backend.Tests
{
    /// <summary>
    /// Which sidecar files become selectable subtitle tracks, what language they claim, and whether they
    /// are machine-generated. Getting the first part wrong exposes a .part file to the player; getting
    /// the last part wrong mislabels every track in the picker.
    /// </summary>
    [TestClass]
    public class SubtitleDiscoveryTests
    {
        // Real headers. The auto sample is YouTube ASR (per-word timing tags); the human one is a
        // hand-written track. Both were taken from files in the dev library.
        private const string AutoVtt =
            "WEBVTT\nKind: captions\nLanguage: en\n\n" +
            "00:00:00.240 --> 00:00:01.990 align:start position:0%\n \n" +
            "While<00:00:00.560><c> waiting</c><00:00:00.800><c> on</c><00:00:01.040><c> a</c>\n\n";

        private const string HumanVtt =
            "WEBVTT\nKind: captions\nLanguage: en\n\n" +
            "00:00:00.400 --> 00:00:03.600\nTaking care of your health can feel overwhelming.\n\n";

        private string root;
        private VideoStorageService storage;

        [TestInitialize]
        public void Setup()
        {
            root = Path.Combine(Path.GetTempPath(), "regard-subtitle-tests", Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(root);
            storage = new VideoStorageService(NullLogger<VideoStorageService>.Instance, StorageManagerFor(root));
        }

        [TestCleanup]
        public void Cleanup()
        {
            try { Directory.Delete(root, recursive: true); } catch { /* best effort */ }
        }

        private void Write(string relativePath, string content)
        {
            var full = Path.Combine(root, relativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(full));
            File.WriteAllText(full, content);
        }

        [TestMethod]
        public async Task PicksOutSubtitlesAndIgnoresEverythingElse()
        {
            Write("Sub/S1E1 - Foo.mp4", "video");
            Write("Sub/S1E1 - Foo.en.vtt", HumanVtt);
            Write("Sub/S1E1 - Foo.ro.vtt", AutoVtt);
            Write("Sub/S1E1 - Foo.info.json", "{}");
            Write("Sub/S1E1 - Foo.f315.webm.part", "partial");
            Write("Sub/S1E1 - Foo.nfo", "<nfo/>");
            Write("Sub/S1E1 - Foo-thumb.jpg", "jpeg");
            Write("Sub/S1E1 - Foo.en.json3", "{}");     // yt-dlp "best" can emit this; unusable in a track

            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = "Sub/S1E1 - Foo" });

            CollectionAssert.AreEquivalent(
                new[] { "en", "ro" },
                tracks.Select(t => t.Lang).ToArray(),
                "only the vtt/srt sidecars are tracks: " + string.Join(", ", tracks.Select(t => t.Lang)));
        }

        [TestMethod]
        public async Task DoesNotClaimASiblingWithALongerName()
        {
            // Same hazard as the file-ownership tests: "Foo" must not pick up "Foo (Part 2)"'s subtitles.
            Write("Sub/S1E1 - Foo.en.vtt", HumanVtt);
            Write("Sub/S1E1 - Foo (Part 2).de.vtt", HumanVtt);

            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = "Sub/S1E1 - Foo" });

            Assert.AreEqual(1, tracks.Count);
            Assert.AreEqual("en", tracks[0].Lang);
        }

        [TestMethod]
        public async Task HandlesATitleContainingASlash()
        {
            // A video title with a slash makes yt-dlp create a directory, so the output prefix is the
            // segment after it. This exists in the real library ("... part 2/2.en.vtt").
            Write("nanobyte/S2023E0 - Memory management - part 2/2.en.vtt", AutoVtt);
            Write("nanobyte/S2023E0 - Memory management - part 2/2.mp4", "video");

            var tracks = await storage.GetSubtitleFiles(
                new Video { DownloadedPath = "nanobyte/S2023E0 - Memory management - part 2/2" });

            Assert.AreEqual(1, tracks.Count, "the prefix is the part after the slash");
            Assert.AreEqual("en", tracks[0].Lang);
        }

        [TestMethod]
        public async Task WorksWithAnAbsoluteDownloadedPath()
        {
            // DownloadedPath is stored absolute in practice (the path template starts with
            // {DownloadDirectory}), so Path.Combine returns it unchanged. Cover the shipped shape, not
            // just the relative one the other tests use.
            Write("Sub/S1E2 - Abs.en.vtt", HumanVtt);

            var absolute = Path.Combine(root, "Sub/S1E2 - Abs");
            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = absolute });

            Assert.AreEqual(1, tracks.Count);
            Assert.AreEqual("en", tracks[0].Lang);
        }

        [TestMethod]
        public async Task TellsMachineGeneratedCuesFromHumanOnes()
        {
            Write("Sub/S1E1 - Foo.en.vtt", HumanVtt);
            Write("Sub/S1E1 - Foo.ro.vtt", AutoVtt);

            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = "Sub/S1E1 - Foo" });

            Assert.IsFalse(tracks.Single(t => t.Lang == "en").AutoGenerated, "hand-written track");
            Assert.IsTrue(tracks.Single(t => t.Lang == "ro").AutoGenerated, "ASR track");
        }

        [TestMethod]
        public async Task SrtIsNeverReportedAsAutoGenerated()
        {
            // yt-dlp's --convert-subs srt strips the per-word timing tags, so the evidence is gone. Say
            // nothing rather than guess.
            Write("Sub/S1E1 - Foo.en.srt", "1\n00:00:00,400 --> 00:00:03,600\nHello\n\n");

            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = "Sub/S1E1 - Foo" });

            Assert.AreEqual("srt", tracks.Single().Format);
            Assert.IsFalse(tracks.Single().AutoGenerated);
        }

        [TestMethod]
        public async Task AcceptsRegionAndScriptTags()
        {
            Write("Sub/S1E1 - Foo.en-US.vtt", HumanVtt);
            Write("Sub/S1E1 - Foo.zh-Hans.vtt", HumanVtt);
            Write("Sub/S1E1 - Foo.en-orig.vtt", HumanVtt);

            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = "Sub/S1E1 - Foo" });

            CollectionAssert.AreEquivalent(
                new[] { "en-US", "zh-Hans", "en-orig" }, tracks.Select(t => t.Lang).ToArray());
        }

        [TestMethod]
        public async Task NoDownloadedPathMeansNoTracks()
        {
            Write("Sub/S1E1 - Foo.en.vtt", HumanVtt);

            var tracks = await storage.GetSubtitleFiles(new Video { DownloadedPath = null });

            Assert.AreEqual(0, tracks.Count);
        }

        [TestMethod]
        public void LabelsAreHumanReadable()
        {
            Assert.AreEqual("English", SubtitleFile.LabelFor("en", false));
            Assert.AreEqual("Romanian (auto-generated)", SubtitleFile.LabelFor("ro", true));
            Assert.AreEqual("Chinese (Simplified)", SubtitleFile.LabelFor("zh-Hans", false));
        }

        [TestMethod]
        public void OrigSuffixIsPeeledOffRatherThanFedToCultureInfo()
        {
            // CultureInfo does NOT throw on "en-orig" — ICU parses "orig" as a script subtag and returns
            // "English (Orig)". Relying on a catch here would ship that string to the picker.
            Assert.AreEqual("English (original)", SubtitleFile.LabelFor("en-orig", false));
        }

        [TestMethod]
        public void AnUnnameableTagFallsBackToItself()
        {
            // "und" resolves to the invariant culture ("Invariant Language (Invariant Country)"), which is
            // worse than showing the raw tag.
            Assert.AreEqual("und", SubtitleFile.LabelFor("und", false));
        }

        private static StorageManager StorageManagerFor(string downloadRoot)
        {
            var config = new ConfigurationBuilder()
                .AddInMemoryCollection(new Dictionary<string, string>
                {
                    ["DownloadDirectory"] = downloadRoot,
                    ["DataDirectory"] = downloadRoot,
                })
                .Build();
            return new StorageManager(NullLogger<VideoStorageService>.Instance, config);
        }
    }

    /// <summary>SubRip has to become WebVTT or the browser silently shows no cues.</summary>
    [TestClass]
    public class SubtitleConverterTests
    {
        [TestMethod]
        public void AddsTheHeaderAndFixesTheDecimalSeparator()
        {
            string vtt = SubtitleConverter.SrtToVtt(
                "1\n00:00:00,400 --> 00:00:03,600\nHello there\n\n2\n00:00:03,600 --> 00:00:08,320\nAnd again\n");

            StringAssert.StartsWith(vtt, "WEBVTT\n\n");
            StringAssert.Contains(vtt, "00:00:00.400 --> 00:00:03.600");
            StringAssert.Contains(vtt, "00:00:03.600 --> 00:00:08.320");
            Assert.IsFalse(vtt.Contains(","), "no comma separators survive: " + vtt);
            StringAssert.Contains(vtt, "Hello there");
        }

        [TestMethod]
        public void DropsCueCountersButKeepsNumericSubtitleText()
        {
            // "42" as the whole of a cue's text must survive; only a counter directly above a timecode goes.
            string vtt = SubtitleConverter.SrtToVtt("1\n00:00:01,000 --> 00:00:02,000\n42\n\n");

            StringAssert.Contains(vtt, "42");
            Assert.IsFalse(vtt.Contains("\n1\n"), "the cue counter is gone: " + vtt);
        }

        [TestMethod]
        public void StripsAByteOrderMark()
        {
            string vtt = SubtitleConverter.SrtToVtt("﻿1\n00:00:01,000 --> 00:00:02,000\nHi\n");

            StringAssert.StartsWith(vtt, "WEBVTT", "a BOM before WEBVTT breaks parsing in some browsers");
        }

        [TestMethod]
        public void StripsCuePlacementSoAsrTracksAreNotPinnedLeft()
        {
            // YouTube's ASR files put "align:start position:0%" on every cue, which renders them ragged
            // against the left edge while hand-written tracks sit centred. CSS can't fix it — alignment
            // is a cue setting, not a style — so the settings come off here.
            string vtt = SubtitleConverter.ToWebVtt(
                "WEBVTT\n\n00:00:00.240 --> 00:00:01.990 align:start position:0%\nHello\n\n", "vtt");

            StringAssert.Contains(vtt, "00:00:00.240 --> 00:00:01.990");
            Assert.IsFalse(vtt.Contains("align:"), "alignment stripped: " + vtt);
            Assert.IsFalse(vtt.Contains("position:"), "position stripped: " + vtt);
            StringAssert.Contains(vtt, "Hello");
        }

        [TestMethod]
        public void LeavesTimecodesAndCueTextAlone()
        {
            string vtt = SubtitleConverter.ToWebVtt(
                "WEBVTT\n\n00:01:02.500 --> 00:01:05.000\nline one\nline two\n\n", "vtt");

            StringAssert.Contains(vtt, "00:01:02.500 --> 00:01:05.000");
            StringAssert.Contains(vtt, "line one\nline two");
        }

        [TestMethod]
        public void SrtIsConvertedAndNormalisedInOnePass()
        {
            string vtt = SubtitleConverter.ToWebVtt(
                "1\n00:00:01,000 --> 00:00:02,000\nHi\n\n", "srt");

            StringAssert.StartsWith(vtt, "WEBVTT\n\n");
            StringAssert.Contains(vtt, "00:00:01.000 --> 00:00:02.000");
        }

        [TestMethod]
        public void HandlesCrlfAndNonAscii()
        {
            string vtt = SubtitleConverter.SrtToVtt("1\r\n00:00:01,000 --> 00:00:02,000\r\nÎn timp ce așteptați\r\n");

            StringAssert.Contains(vtt, "În timp ce așteptați");
            StringAssert.Contains(vtt, "00:00:01.000 --> 00:00:02.000");
        }
    }
}

using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging.Abstractions;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Regard.Backend.Services;
using Regard.Common.SponsorBlock;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

namespace Regard.Backend.Tests.Services
{
    /// <summary>
    /// The watch page fetches SponsorBlock live, which meant a request to sponsor.ajay.app on every load
    /// of the same video. GetSkipSegmentsCached puts a short in-memory cache in front of that. These
    /// pin down the two things that make the cache safe: it actually collapses repeat calls into one HTTP
    /// request, and it never hands back the list it holds (callers mutate Skip, which must not leak back).
    /// </summary>
    [TestClass]
    public class SponsorBlockClientCacheTests
    {
        // Canned response: one sponsor segment. actionType=skip so the client keeps it.
        private const string OneSponsorSegment =
            "[{\"segment\":[10.0,20.0],\"category\":\"sponsor\",\"actionType\":\"skip\"}]";

        // Minimal counting handler — no mocking library in this project.
        private sealed class CountingHandler : HttpMessageHandler
        {
            private readonly string body;
            private readonly HttpStatusCode status;
            public int Calls { get; private set; }

            public CountingHandler(string body, HttpStatusCode status = HttpStatusCode.OK)
            {
                this.body = body;
                this.status = status;
            }

            protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
            {
                Calls++;
                return Task.FromResult(new HttpResponseMessage(status)
                {
                    Content = new StringContent(body),
                });
            }
        }

        private static SponsorBlockClient MakeClient(CountingHandler handler, out IMemoryCache cache)
        {
            var http = new HttpClient(handler) { BaseAddress = new Uri("https://sponsor.ajay.app") };
            cache = new MemoryCache(new MemoryCacheOptions());
            return new SponsorBlockClient(http, cache, NullLogger<SponsorBlockClient>.Instance);
        }

        private static readonly List<string> AllCats = SponsorBlockActions.Categories.ToList();

        [TestMethod]
        public async Task Second_lookup_of_the_same_video_is_served_from_cache()
        {
            var handler = new CountingHandler(OneSponsorSegment);
            var client = MakeClient(handler, out _);

            var first = await client.GetSkipSegmentsCached("vid1", AllCats);
            var second = await client.GetSkipSegmentsCached("vid1", AllCats);

            Assert.AreEqual(1, handler.Calls, "the second lookup should not hit the network");
            Assert.AreEqual(1, first.Count);
            Assert.AreEqual(1, second.Count);
            Assert.AreEqual("sponsor", second[0].Category);
        }

        [TestMethod]
        public async Task A_different_video_is_fetched_separately()
        {
            var handler = new CountingHandler(OneSponsorSegment);
            var client = MakeClient(handler, out _);

            await client.GetSkipSegmentsCached("vid1", AllCats);
            await client.GetSkipSegmentsCached("vid2", AllCats);

            Assert.AreEqual(2, handler.Calls, "a distinct video id must not share the cache entry");
        }

        [TestMethod]
        public async Task Callers_get_independent_copies_so_mutating_Skip_cannot_poison_the_cache()
        {
            var handler = new CountingHandler(OneSponsorSegment);
            var client = MakeClient(handler, out _);

            var first = await client.GetSkipSegmentsCached("vid1", AllCats);
            // Simulate what VideoController does: mark the segment to skip for this request's config.
            first[0].Skip = true;

            var second = await client.GetSkipSegmentsCached("vid1", AllCats);

            Assert.IsFalse(second[0].Skip, "the cached segment's Skip must not carry over between callers");
            Assert.AreNotSame(first[0], second[0], "each call should return fresh segment objects");
            Assert.AreEqual(1, handler.Calls);
        }

        [TestMethod]
        public async Task An_empty_result_is_cached_too_so_the_common_no_segments_case_stops_refetching()
        {
            // 404 is SponsorBlock's documented "no segments" response -> empty list, and it should cache.
            var handler = new CountingHandler("", HttpStatusCode.NotFound);
            var client = MakeClient(handler, out _);

            var first = await client.GetSkipSegmentsCached("vid1", AllCats);
            var second = await client.GetSkipSegmentsCached("vid1", AllCats);

            Assert.AreEqual(0, first.Count);
            Assert.AreEqual(0, second.Count);
            Assert.AreEqual(1, handler.Calls, "a no-segments result should also be cached");
        }

        [TestMethod]
        public async Task Empty_video_or_no_categories_never_touches_the_network()
        {
            var handler = new CountingHandler(OneSponsorSegment);
            var client = MakeClient(handler, out _);

            var noVid = await client.GetSkipSegmentsCached("", AllCats);
            var noCats = await client.GetSkipSegmentsCached("vid1", new List<string>());

            Assert.AreEqual(0, noVid.Count);
            Assert.AreEqual(0, noCats.Count);
            Assert.AreEqual(0, handler.Calls);
        }
    }
}
